#!/usr/bin/env node
// Writes src/live-room/core/ from the lab's protocol in tests/live-room/lab/core/.
// Every planted("…") call becomes false, and esbuild folds the dead branches away,
// so the product core is the lab core with no planted defect left in it.
// `--check` exits 1 when a generated file differs from what the lab copy gives.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { transformSync } from "esbuild";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
export const LAB_CORE = path.join(ROOT, "tests/live-room/lab/core");
export const OUT = path.join(ROOT, "src/live-room/core");

export function unplant(source, force = []) {
  let out = "";
  let at = 0;
  for (;;) {
    const hit = source.indexOf("planted(", at);
    if (hit < 0) return out + source.slice(at);
    if (/[\w$.]/.test(source[hit - 1] ?? "")) {
      out += source.slice(at, hit + 8);
      at = hit + 8;
      continue;
    }
    let depth = 1;
    let i = hit + 8;
    for (; depth; i++) {
      if (i >= source.length) throw new Error(`unclosed planted( at offset ${hit}`);
      const c = source[i];
      if (c === "(") depth++;
      else if (c === ")") depth--;
      else if (c === '"' || c === "'" || c === "`") {
        for (i++; source[i] !== c; i++) if (source[i] === "\\") i++;
      }
    }
    const arg = source.slice(hit + 8, i - 1);
    const forced = force.filter((name) => arg.includes(`"${name}"`));
    out += `${source.slice(at, hit)}${forced.length ? `${JSON.stringify(forced)}.includes(${arg})` : "false"}`;
    at = i;
  }
}

// `force` names planted defects to switch on instead of off: tests use it to build a
// product core with one known defect and prove the runner fails it.
export function generate(name, source, { force = [] } = {}) {
  const body = unplant(source.replace(/\r\n/g, "\n").replace(/^import \{ planted \} from "\.\/planted\.mjs";\n/m, ""), force);
  if (/\bplanted\b/.test(body)) throw new Error(`${name}: a planted reference survived`);
  const code = transformSync(body, { loader: "js", format: "esm", minifySyntax: true, treeShaking: true, legalComments: "none", define: { "process.env": "{}" } }).code;
  const relinked = code.replace(/from "\.\/([\w-]+)\.mjs"/g, 'from "./$1.js"');
  if (/\.mjs"/.test(relinked)) throw new Error(`${name}: an import still names a .mjs file`);
  if (/\bprocess\b/.test(relinked)) throw new Error(`${name}: a process reference survived`);
  return `// Generated by scripts/build-live-room-core.mjs from tests/live-room/lab/core/${name}.\n// Edit the lab copy, then run npm run build:live-room-core.\n${relinked}`;
}

// Every planted defect the lab core can switch on (a name in the lab's PLANTS that
// appears in one of its planted(...) calls).
export function corePlants() {
  const PLANTS = Object.fromEntries([...fs.readFileSync(path.join(LAB_CORE, "planted.mjs"), "utf8").matchAll(/^ {2}"([\w-]+)": /gm)].map(([, name]) => [name, true]));
  const names = new Set();
  for (const name of fs.readdirSync(LAB_CORE)) {
    if (!name.endsWith(".mjs") || name === "planted.mjs") continue;
    const calls = fs.readFileSync(path.join(LAB_CORE, name), "utf8").match(/\bplanted\((?:[^()]|\([^()]*\))*\)/g) ?? [];
    for (const call of calls) for (const [, plant] of call.matchAll(/"([\w-]+)"/g)) if (plant in PLANTS) names.add(plant);
  }
  return [...names].sort();
}

export function writeCore(dir, files) {
  fs.mkdirSync(dir, { recursive: true });
  for (const [name, text] of Object.entries(files)) fs.writeFileSync(path.join(dir, name), text);
}

export function strays(files) {
  if (!fs.existsSync(OUT)) return [];
  return fs.readdirSync(OUT).filter((name) => !(name in files));
}

export function buildCore({ force = [] } = {}) {
  const files = {};
  for (const name of fs.readdirSync(LAB_CORE).sort()) {
    if (!name.endsWith(".mjs") || name === "planted.mjs") continue;
    files[name.replace(/\.mjs$/, ".js")] = generate(name, fs.readFileSync(path.join(LAB_CORE, name), "utf8"), { force });
  }
  return files;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const files = buildCore();
  if (process.argv.includes("--check")) {
    const stale = Object.entries(files).filter(([name, text]) => {
      const at = path.join(OUT, name);
      return !fs.existsSync(at) || fs.readFileSync(at, "utf8") !== text;
    });
    for (const [name] of stale) console.error(`Stale: src/live-room/core/${name} (run npm run build:live-room-core)`);
    for (const name of strays(files)) console.error(`Not generated: src/live-room/core/${name} (the lab has no core/${name.replace(/\.js$/, ".mjs")})`);
    if (stale.length || strays(files).length) process.exit(1);
    console.log(`In sync: ${Object.keys(files).length} files in src/live-room/core`);
  } else {
    writeCore(OUT, files);
    console.log(`Wrote ${Object.keys(files).length} files to src/live-room/core`);
  }
}
